const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (e) => ({ k: 'e', v: e })
const num = (v) => ({ k: 'n', v })
const ADDR = /^([A-Z]{1,2})([0-9]{1,3})$/

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'values' && mode[0] !== 'deps')) fail('error: usage: cli.js values|deps')

function colIndex(s) {
  return s.length === 1 ? s.charCodeAt(0) - 64 : 26 + (s.charCodeAt(0) - 65) * 26 + (s.charCodeAt(1) - 64)
}
function colName(i) {
  if (i <= 26) return String.fromCharCode(64 + i)
  const j = i - 27
  return String.fromCharCode(65 + Math.floor(j / 26)) + String.fromCharCode(65 + (j % 26))
}
function parseAddr(w) {
  const m = ADDR.exec(w.toUpperCase())
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  return { col: colIndex(m[1]), row }
}
const keyOf = (c, r) => colName(c) + r

// ---- read sheet
const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const cells = new Map()
lines.forEach((raw, i) => {
  const s = raw.replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') return
  const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(s)
  const addr = m[1]
  const p = parseAddr(addr)
  if (!p) fail(`error: line ${i + 1}: invalid cell address ${addr}`)
  const key = keyOf(p.col, p.row)
  if (cells.has(key)) fail(`error: line ${i + 1}: cell ${key} is declared twice`)
  cells.set(key, { col: p.col, row: p.row, key, content: m[2] })
})

// ---- parser
function tokenize(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const c = src[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length
    } else if ((m = /^(<>|<=|>=|[<>=^*\/+\-(),:])/.exec(src.slice(i)))) {
      toks.push({ t: 'op', v: m[0] }); i += m[0].length
    } else return null
  }
  return toks
}

function parse(src) {
  const toks = tokenize(src)
  if (!toks) return null
  let p = 0
  const bad = new Error('parse')
  const isOp = (v) => toks[p] && toks[p].t === 'op' && toks[p].v === v
  function cmp() {
    let l = add()
    while (toks[p] && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { t: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { t: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { t: 'un', op, e: unary() } }
    return primary()
  }
  function arg() {
    const a = toks[p], b = toks[p + 1], c = toks[p + 2]
    if (a && a.t === 'word' && b && b.t === 'op' && b.v === ':') {
      if (!c || c.t !== 'word') throw bad
      const d = toks[p + 3]
      if (d && d.t === 'op' && d.v === '(') throw bad
      const e = toks[p + 3]
      if (!(e && e.t === 'op' && (e.v === ',' || e.v === ')'))) throw bad
      if (/^(TRUE|FALSE)$/i.test(a.v) || /^(TRUE|FALSE)$/i.test(c.v)) throw bad
      p += 3
      return { t: 'range', a: a.v, b: c.v }
    }
    return cmp()
  }
  function primary() {
    const tk = toks[p]
    if (!tk) throw bad
    if (tk.t === 'num') { p++; return { t: 'num', v: tk.v } }
    if (tk.t === 'op' && tk.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) throw bad
      p++
      return e
    }
    if (tk.t === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = [arg()]
        while (isOp(',')) { p++; args.push(arg()) }
        if (!isOp(')')) throw bad
        p++
        return { t: 'call', name: tk.v.toUpperCase(), args }
      }
      const u = tk.v.toUpperCase()
      if (u === 'TRUE') return { t: 'bool', v: true }
      if (u === 'FALSE') return { t: 'bool', v: false }
      return { t: 'ref', name: tk.v }
    }
