const memo = new Map()
const visiting = new Set()
const fin = (v) => (Number.isFinite(v) ? num(v) : err('#DIV/0!'))

function literal(content) {
  if (content === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
  if (ERRS.includes(content)) return err(content)
  return { k: 't', v: content }
}

function cellValue(key) {
  const c = cells.get(key)
  if (!c) return num(0)
  if (memo.has(key)) return memo.get(key)
  if (visiting.has(key)) return err('#CYCLE!')
