  let r
  if (c.content[0] === '=') {
    const ast = parse(c.content.slice(1))
    r = ast ? evalNode(ast) : err('#ERR!')
  } else r = literal(c.content)
  visiting.delete(key)
  memo.set(key, r)
  return r
