      const a = toNum(l)
      if (a.k === 'e') return a
      const b = toNum(r)
      if (b.k === 'e') return b
      switch (n.op) {
        case '+': return fin(a.v + b.v)
        case '-': return fin(a.v - b.v)
        case '*': return fin(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
        default: return fin(Math.pow(a.v, b.v))
      }
    }
    case 'call': return evalCall(n)
  }
}

function evalCall(n) {
  const name = n.name
  const args = n.args
  const agg = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
  if (!agg.includes(name) && name !== 'ABS' && name !== 'IF') return err('#NAME?')
  if (name === 'ABS' && args.length !== 1) return err('#ERR!')
  if (name === 'IF' && args.length !== 3) return err('#ERR!')
  if (name === 'ABS' || name === 'IF') {
    if (args.some((a) => a.t === 'range')) return err('#ERR!')
  }
  if (name === 'IF') {
    const c = evalNode(args[0])
    if (c.k === 'e') return c
    let truth
    if (c.k === 'b') truth = c.v
    else if (c.k === 'n') truth = c.v !== 0
    else return err('#VALUE!')
    return evalNode(truth ? args[1] : args[2])
  }
  const vals = []
  for (const a of args) {
    if (a.t === 'range') vals.push(...rangeValues(a.a, a.b))
    else vals.push(evalNode(a))
  }
  const firstErr = vals.find((v) => v.k === 'e')
  if (firstErr) return firstErr
  if (name === 'COUNT') return num(vals.filter((v) => v.k === 'n').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.k === 'e') return x
    nums.push(x.v)
  }
  switch (name) {
    case 'ABS': return num(Math.abs(nums[0]))
    case 'SUM': return fin(nums.reduce((a, b) => a + b, 0))
    case 'MIN': return num(Math.min(...nums))
    case 'MAX': return num(Math.max(...nums))
    default: return fin(nums.reduce((a, b) => a + b, 0) / nums.length)
  }
}

// ---- output
function show(v) {
  if (v.k === 'e') return v.v
  if (v.k === 't') return v.v
  if (v.k === 'b') return v.v ? 'TRUE' : 'FALSE'
  return String(Number(v.v.toPrecision(10)))
}

function collect(n, set) {
  switch (n.t) {
    case 'ref': { const p = parseAddr(n.name); if (p) set.set(keyOf(p.col, p.row), p); break }
    case 'range': {
      const p = parseAddr(n.a), q = parseAddr(n.b)
      if (!p || !q) break
      for (let c = Math.min(p.col, q.col); c <= Math.max(p.col, q.col); c++)
        for (let r = Math.min(p.row, q.row); r <= Math.max(p.row, q.row); r++) set.set(keyOf(c, r), { col: c, row: r })
      break
    }
    case 'un': collect(n.e, set); break
    case 'bin': collect(n.l, set); collect(n.r, set); break
    case 'call': n.args.forEach((a) => collect(a, set)); break
  }
}

const sorted = [...cells.values()].sort((a, b) => a.col - b.col || a.row - b.row)
const out = []
for (const c of sorted) {
  if (mode[0] === 'values') out.push(`${c.key}=${show(cellValue(c.key))}`)
  else {
    const set = new Map()
    if (c.content[0] === '=') {
      const ast = parse(c.content.slice(1))
      if (ast) collect(ast, set)
    }
    const ds = [...set.values()].sort((a, b) => a.col - b.col || a.row - b.row)
    out.push(`${c.key}:` + ds.map((d) => ' ' + keyOf(d.col, d.row)).join(''))
  }
}
process.stdout.write(out.length ? out.join('\n') + '\n' : '')

